import{z as s,x as n,o as A,c as d,q as o,j as l,D as E,d as r,s as B,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"阿罗不可能定理","description":"","frontmatter":{"title":"阿罗不可能定理","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/arrow-impossibility.md","filePath":"econ/arrow-impossibility.md","lastUpdated":1791413859000}'),p={name:"econ/arrow-impossibility.md"};function m(I,a,D,h,c,C){const i=n("Mermaid");return A(),d("div",null,[a[2]||(a[2]=o('<h1 id="阿罗不可能定理" tabindex="-1">阿罗不可能定理 <a class="header-anchor" href="#阿罗不可能定理" aria-label="Permalink to &quot;阿罗不可能定理&quot;">​</a></h1><div class="epigraph"><p>若社会排序必须对一切偏好剖面有定义，满足弱帕累托与无关方案独立性，并且不独裁，则不存在这样的加总规则。</p><footer>—— Arrow, Social Choice and Individual Values, 1951；1963 第二版</footer></div><p><a href="/econ/mirrlees-income">上一课</a>（最优所得税）的规划假定有一个社会福利函数 \\(W\\)，把商品税写成约束最优。缺口是 \\(W\\) 从哪来。若只有序数偏好剖面，能否用一组公理把个人排序收成社会排序？Arrow 说：不能。本课钉公理冲突，不是市场失灵或次优楔子的重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对象：有限方案集 \\(|X|\\ge 3\\)，个人 \\(i\\) 的严格（或弱）排序 \\(R_i\\)，剖面 \\((R_1,\\ldots,R_n)\\)。社会福利泛函把剖面对成社会排序 \\(R\\)。Arrow 的条件：</p><ul><li>无限制定义域：一切剖面都可接受；</li><li>弱帕累托：人人严格偏好 \\(x\\) 于 \\(y\\)，则社会也如此；</li><li>无关方案独立性（IIA）：\\(x\\) 与 \\(y\\) 的社会相对位置，只取决于各人在 \\(\\{x,y\\}\\) 上的排序；</li><li>非独裁：不存在一个人，其严格偏好永远变成社会严格偏好。</li></ul><p>定理：不存在同时满足四条的加总。Condorcet 循环（甲乙丙三人、三方案的石头剪刀布）是教具：多数规则满足帕累托与非独裁，但循环不是排序，若用「淘汰赛」打破循环又往往踩 IIA。</p><h3 id="这不是「市场会失灵」" tabindex="-1">这不是「市场会失灵」 <a class="header-anchor" href="#这不是「市场会失灵」" aria-label="Permalink to &quot;这不是「市场会失灵」&quot;">​</a></h3><p>外部性、公共品、Ramsey 楔子谈的是配置能不能分权。本课谈的是规范加总：就算完全市场把帕累托集摆在桌上，社会要在集上挑哪一点，序数加总没有免费的规则。第二定理用总额转移挑点，已经假定计划者知道要去哪一点；Arrow 说「要去哪」本身加总不出来。</p><p><span class="marginnote">IIA 禁止用「对第三方案 \\(z\\) 的看法」来决定 \\(x\\) 对 \\(y\\)。Borda 计数用名次加总，改一个无关方案的插入可以翻转 \\(x,y\\)，故非 IIA。多数两两比较是 IIA 的，但可以不传递。</span></p><p><span class="marginnote">术语翻译：「Condorcet 循环」是多数规则的死循环——三人选三方案，甲乙胜乙丙、乙丙胜丙甲、丙甲又胜甲乙，两两多数各赢一次。每个局部多数都「正确」，合起来却没有赢家：社会排序的传递性断了，这正是要加总规则的理由，也是它崩溃的入口。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>证明骨架：由帕累托，全联盟是决定性的（其共同严格偏好即社会偏好）。IIA 加无限制域，把决定性从大联盟传到子联盟，直到收缩为单人——独裁。本课要的是这条收缩，不是投票程序清单。</p><p>逃避条款必须改公理，不能改口号。单峰偏好（Black）限制定义域，中位选民给出多数均衡。基数效用加人际比较（Harsanyi 功利）换掉序数与 IIA 的搭配。两人、两方案时多数规则没事，\\(|X|\\ge 3\\) 才炸。</p>',14)),(A(),l(t,null,{default:E(()=>[B(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22Ramsey%20%E7%94%A8%E7%9A%84%20W%22%5D%20--%3E%20ASK%5B%22W%20%E4%BB%8E%E5%BA%8F%E6%95%B0%E5%89%96%E9%9D%A2%E6%9D%A5%E5%90%97%22%5D%0A%20%20ASK%20--%3E%20AX%5B%22%E5%AE%9A%E4%B9%89%E5%9F%9F%E3%80%81%E5%B8%95%E7%B4%AF%E6%89%98%E3%80%81IIA%E3%80%81%E9%9D%9E%E7%8B%AC%E8%A3%81%22%5D%0A%20%20AX%20--%3E%20IMP%5B%22%E4%B8%8D%E5%8F%AF%E8%83%BD%22%5D%0A%20%20IMP%20--%3E%20ESC%5B%22%E9%99%90%E5%AE%9A%E4%B9%89%E5%9F%9F%E6%88%96%E4%BA%BA%E9%99%85%E6%AF%94%E8%BE%83%22%5D%0A%20%20IMP%20--%3E%20GAME%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E4%B8%8D%E5%86%8D%E5%81%87%E5%AE%9A%E6%9C%89%20W%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"四条一起空，是因为传递的社会排序太强，而 IIA 又不许借用第三方案来恢复传递。无限制域保证循环剖面合法；帕累托强迫社会跟着一致意见走；非独裁禁止指定一个人当社会。少任何一条都可以造出规则：独裁满足前三条；Borda 放弃 IIA；多数放弃传递。",-1)),a[5]||(a[5]=e("p",null,"第一张图是公理冲突的路线图；这一张画证明本身的收缩链——「决定性」如何从全体选民一路二分到单人，矛盾在哪一步显形。",-1)),(A(),l(t,null,{default:E(()=>[B(i,{id:"mermaid-69",class:"mermaid",graph:"flowchart%20TD%0A%20%20ALL%5B%22%E5%85%A8%E4%BD%93%E9%80%89%E6%B0%91%EF%BC%9A%E7%94%B1%E5%B8%95%E7%B4%AF%E6%89%98%EF%BC%8C%E5%85%B7%E5%86%B3%E5%AE%9A%E6%80%A7%22%5D%20--%3E%20SHRINK%5B%22IIA%20%2B%20%E6%97%A0%E9%99%90%E5%88%B6%E5%9F%9F%EF%BC%9A%E5%86%B3%E5%AE%9A%E6%80%A7%E4%BC%A0%E7%BB%99%E5%AD%90%E9%9B%86%22%5D%0A%20%20SHRINK%20--%3E%20HALF%5B%22%E4%BB%BB%E4%B8%80%E6%9C%89%E5%86%B3%E5%AE%9A%E6%80%A7%E7%9A%84%E8%81%94%E7%9B%9F%EF%BC%8C%E5%85%B6%E4%B8%80%E5%8D%8A%E4%BB%8D%E6%9C%89%E5%86%B3%E5%AE%9A%E6%80%A7%22%5D%0A%20%20HALF%20--%3E%20SHRINK%0A%20%20HALF%20--%3E%20ONE%5B%22%E4%B8%8D%E6%96%AD%E6%94%B6%E7%BC%A9%EF%BC%8C%E7%9B%B4%E5%88%B0%E5%8F%AA%E5%89%A9%E5%8D%95%E4%BA%BA%22%5D%0A%20%20ONE%20--%3E%20DICT%5B%22%E6%AD%A4%E4%BA%BA%E5%AF%B9%E6%9F%90%E5%AF%B9%E6%96%B9%E6%A1%88%E6%9C%89%E5%86%B3%E5%AE%9A%E6%80%A7%EF%BC%8C%E5%B9%B6%E5%8F%AF%E6%89%A9%E5%B1%95%E6%88%90%E7%8B%AC%E8%A3%81%22%5D%0A%20%20DICT%20--%3E%20CONTRA%5B%22%E4%B8%8E%E3%80%8C%E9%9D%9E%E7%8B%AC%E8%A3%81%E3%80%8D%E7%9B%B8%E6%92%9E%EF%BC%9A%E5%9B%9B%E6%9D%A1%E4%B8%8D%E7%9B%B8%E5%AE%B9%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">直觉类比：证明像「二分收缩」——全体联盟有决定权；IIA 逼出「有决定权的联盟，其一半也必有」；一路对半切下去，最后剩下的一个人握有决定权，恰与「非独裁」撞车。四条公理的矛盾全部压在这条收缩链上，不靠任何具体投票程序。</span></p><p>Gibbard–Satterthwaite 把同一紧张写成策略：非独裁的社会选择，在广泛定义域上无法让说真话成为占优。那是后课机制的伏笔；本课停在偏好加总，不进入博弈。</p><h3 id="福利权重不是逃出定理的后门" tabindex="-1">福利权重不是逃出定理的后门 <a class="header-anchor" href="#福利权重不是逃出定理的后门" aria-label="Permalink to &quot;福利权重不是逃出定理的后门&quot;">​</a></h3><p>Ramsey–Diamond 公式里的分配特征，已经在用加权的边际效用——那是基数加人际比较，正好站在 Arrow 序数框架外面。承认比较，就可以写 \\(W\\)；不承认，计划者的目标函数没有公理化来源。市场失灵课序用的 \\(W\\) 一直是后一种实用主义，本课把它的代价写明。</p><p><span class="marginnote">Arrow 1951 第一版的条件略有不同；1963 第二版的四条是教科书标准。Sen 后来强调：放宽「社会必须是完整排序」或引入个人权利，会得到另一族不可能。主干只钉 Arrow 四条。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>定理不管偏好从哪来，也不给实证投票的预测。单峰、中间选民、概率投票是政治经济学，不是本课的逃逸证明。也不要把不可能写成「因此不要政府」——配置问题仍在，只是加总规则没有免费午餐。</p><p><span class="marginnote">常见误区：把定理读成「民主没用」。它否定的只是「处处有定义、且满足四条的序数加总规则」；限定单峰偏好（比如一维左右谱上的排序）多数规则照样有均衡，承认人际比较也能写出 \\(W\\)。要逃的不是口号，是某一条公理。</span></p><p>市场失灵课序还没走完：缺市场、公共品、归宿、DWL、次优、Ramsey，最后加总规则本身，之后还有中位选民与孔多塞循环两课投票。博弈课在投票之后从个人策略起，不再假定桌上有一个被所有人接受的 \\(W\\)。</p><p>后课默认：序数偏好加 IIA 与帕累托，不能给出非独裁的社会排序；要用 \\(W\\)，必须另加基数、人际比较或定义域限制。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Ramsey 的 \\(W\\) 不是从序数剖面免费加总出来的。</li><li>无限制定义域、帕累托、IIA、非独裁，四条不相容。</li><li>循环是教具；决定性联盟收缩才是证明。</li><li>单峰或人际比较可以逃，那是改公理。</li><li>出处：Arrow, <em>Social Choice and Individual Values</em>, 1951/1963。</li></ul>',12))])}const _=s(p,[["render",m]]);export{F as __pageData,_ as default};
